const fs = require('fs');
const plan = JSON.parse(fs.readFileSync('.exp_agent/round_01/plan.json', 'utf8'));
const report = JSON.parse(fs.readFileSync('.exp_agent/round_01/completion.json', 'utf8'));
const schema = JSON.parse(fs.readFileSync('.exp_agent/round_01/completion-schema.json', 'utf8'));
const expectedRules = plan.rules.map(r => r.rule);
if (JSON.stringify(report.selected_rules) "'!== JSON.stringify(expectedRules)) throw new Error('"'selected_rules do not exactly match plan');
if (report.blocked.length || report.unresolved_external.length) throw new Error('blocked or unresolved_external is non-empty');
const expectedLocations = new Map();
for (const rule of plan.rules) for (const file of rule.files) expectedLocations.set("'`${rule.rule}|${file.relative_path}`, file.locations.map(l => `${l.line}:${l.column}`));
if (report.entity_repairs.length !== expectedLocations.size) throw new Error('"'entity repair group count mismatch');
for (const repair of report.entity_repairs) {
  const key = "'`${repair.rule}|${repair.relative_path}`;
  if (!expectedLocations.has(key)) throw new Error(`unexpected repair ${key}`);
  const actual = repair.locations.map(l => `${l.line}:${l.column}`);
  if (JSON.stringify(actual) !== JSON.stringify(expectedLocations.get(key))) throw new Error(`location mismatch ${key}`);
  if (!repair.entities.length || !repair.evidence.length || repair.status !== '"'repaired' || "'!repair.transformation) throw new Error(`invalid repair fields ${key}`);
}
for (const required of schema.required) if (!(required in report)) throw new Error(`missing ${required}`);
console.log(`completion report checks passed: ${report.entity_repairs.length} groups, ${[...expectedLocations.values()].flat().length} locations`);
